function i_c_out = mfun_gfl_current_reference(p_g_ref, q_g_ref, u_g, p)
%MFUN_GFL_CURRENT_REFERENCE Block compute_output of the control system.
%   Generated by motulator_export from the MATLAB port of motulator. The parameters are
%   the fields of the struct p (from the mask, [] as NaN).
% Current reference from the power references and the PCC voltage
i_c = gfl_current_reference(p_g_ref, q_g_ref, u_g);
i_c_out = complex_out(i_c);
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function i_c_ref = gfl_current_reference(p_g_ref, q_g_ref, u_g)
%GFL_CURRENT_REFERENCE Current reference from the power references and the filtered
%   PCC voltage magnitude u_g (CurrentVectorController.compute_output, before the
%   CurrentLimiter).
i_c_ref = (p_g_ref - 1i*q_g_ref)/(1.5*u_g);
end
